    out = [[0] * 6 for _ in range(3)]
    seen = set()

    # Each T is represented by its 3-by-3 bounding box. Encode its
    # orientation in the corresponding half of the output.
    for r in range(h - 2):
        for c in range(w - 2):
            cells = {(i, j) for i in range(3) for j in range(3)
                     if grid[r+i][c+j] == 2}
            if len(cells) != 4:
                continue
            orientations = {
                frozenset({(0,1),(1,0),(1,1),(1,2)}): (0, 0, 3),
                frozenset({(0,0),(0,1),(0,2),(1,1)}): (2, 0, 3),
                frozenset({(0,0),(1,0),(1,1),(2,0)}): (0, 2, 3),
                frozenset({(0,1),(1,0),(1,1),(2,1)}): (2, 2, 3),
                frozenset({(0,1),(1,0),(1,1),(1,2)}): (0, 3, 1),
                frozenset({(0,0),(0,1),(0,2),(1,1)}): (0, 3, 1),
                frozenset({(0,0),(1,0),(1,1),(2,0)}): (0, 5, 1),
                frozenset({(0,1),(1,0),(1,1),(2,1)}): (2, 3, 1),
            }
            key = frozenset(cells)
            if key in orientations:
                rr, cc, val = orientations[key]
                out[rr][cc] = val
    return out
